 p=argparse.ArgumentParser();p.add_argument('--candidate',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();assert not a.output.exists();a.output.mkdir(parents=True);f=a.output/'actual-lifetime.c';f.write_text(TEST);cc=ROOT/'tools/external/llvm-mingw-20260616-ucrt-x86_64/bin/i686-w64-mingw32-clang.exe';cmd=[str(cc),'-O1','-std=gnu11','-Wall','-Wextra','-Werror','-I'+str(a.candidate),str(a.candidate/'om_sram_core.c'),str(a.candidate/'om_sram_lifetime.c'),str(f),'-o',str(a.output/'fixture.exe')];r=subprocess.run(cmd,capture_output=True);(a.output/'compile.stderr').write_bytes(r.stderr);assert not r.returncode,r.stderr.decode();r=subprocess.run([str(a.output/'fixture.exe')],capture_output=True);(a.output/'run.stderr').write_bytes(r.stderr);assert not r.returncode,r.stderr.decode();proof=json.loads(r.stdout);pins={str(p):sha(p)for p in[Path(__file__),cc,f,a.output/'fixture.exe',a.candidate/'om_sram_core.c',a.candidate/'om_sram_core.h',a.candidate/'om_sram_lifetime.c',a.candidate/'om_sram_lifetime.h']};r={'status':'PASS_ACTUAL_32BIT_SRAM_LIFETIME_RING_RESET_CLEAR_ADAPTER_CONTROLS_ONLY','hardware_accessed':False,'firmware_eligible':False,**proof,'pins':pins,'limits':'Actualadapter/coreC, arraymemory/fakeobservedregisterinput; noMMIO/R20hooks/ringhardware/writecoverageproof. RejectsNETSSresetwithliveallocs, noautomaticreservationpromotion.'};(a.output/'result.json').write_text(json.dumps(r,indent=2)+'\n');print(json.dumps(r,indent=2))
